import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const root = path.dirname(fileURLToPath(import.meta.url));
const dbPath = process.env.DB_PATH || path.join(root, 'workboard.sqlite');
const db = new DatabaseSync(dbPath);
db.exec(`CREATE TABLE IF NOT EXISTS projects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  archived INTEGER NOT NULL DEFAULT 0
)`);
try { db.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0'); } catch {}
try { db.exec("ALTER TABLE projects ADD COLUMN default_priority TEXT NOT NULL DEFAULT 'Normal'"); } catch {}
const getProject = db.prepare('SELECT id, name, archived, default_priority AS defaultPriority FROM projects WHERE id = ?');
const setArchived = db.prepare('UPDATE projects SET archived = ? WHERE id = ?');
const renameProject = db.prepare('UPDATE projects SET name = ? WHERE id = ? AND archived = 0');
const createProject = db.prepare('INSERT INTO projects (name) VALUES (?)');
db.exec(`CREATE TABLE IF NOT EXISTS tasks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  priority TEXT NOT NULL DEFAULT 'Normal' CHECK (priority IN ('Low', 'Normal', 'High'))
)`);
try { db.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal'"); } catch {}
// Keep additive migrations explicit so every pre-existing database receives the
// persistence columns before request handlers prepare their statements.
const taskColumns = new Set(db.prepare('PRAGMA table_info(tasks)').all().map(column => column.name));
if (!taskColumns.has('due_date')) db.exec('ALTER TABLE tasks ADD COLUMN due_date TEXT');
if (!taskColumns.has('notes')) db.exec("ALTER TABLE tasks ADD COLUMN notes TEXT NOT NULL DEFAULT ''");
// Re-read schema after additive migrations before preparing persistence queries.
const migratedTaskColumns = new Set(db.prepare('PRAGMA table_info(tasks)').all().map(column => column.name));
if (!migratedTaskColumns.has('due_date') || !migratedTaskColumns.has('notes')) {
  throw new Error('Task persistence schema migration failed');
}
try { db.exec('ALTER TABLE tasks ADD COLUMN sort_order INTEGER NOT NULL DEFAULT 0'); } catch {}
db.exec('UPDATE tasks SET sort_order = id WHERE sort_order = 0');
db.exec(`CREATE TABLE IF NOT EXISTS task_project_positions (
  task_id INTEGER NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
  project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  position INTEGER NOT NULL,
  PRIMARY KEY (task_id, project_id)
)`);
db.exec(`INSERT OR IGNORE INTO task_project_positions (task_id, project_id, position)
  SELECT id, project_id, sort_order FROM tasks`);
const listTasks = db.prepare(`SELECT t.id, t.project_id AS projectId, t.title, t.completed, t.priority, t.due_date AS dueDate, t.notes
  FROM tasks t LEFT JOIN task_project_positions p ON p.task_id = t.id AND p.project_id = t.project_id
  WHERE t.project_id = ? ORDER BY p.position, t.id`);
const createTask = db.prepare('INSERT INTO tasks (project_id, title, priority, sort_order) VALUES (?, ?, ?, COALESCE((SELECT MAX(sort_order) + 1 FROM tasks WHERE project_id = ?), 0))');
const addTaskPosition = db.prepare('INSERT INTO task_project_positions (task_id, project_id, position) VALUES (?, ?, ?)');
const nextTaskPosition = db.prepare('SELECT COALESCE(MAX(position) + 1, 0) AS position FROM task_project_positions WHERE project_id = ?');
const getTaskPosition = db.prepare('SELECT position FROM task_project_positions WHERE task_id = ? AND project_id = ?');
const moveTask = db.prepare('UPDATE tasks SET project_id = ?, sort_order = ? WHERE id = ? AND project_id = ?');
const getTask = db.prepare('SELECT id, project_id AS projectId, title, completed, priority, due_date AS dueDate, notes FROM tasks WHERE id = ?');
const updateDueDate = db.prepare('UPDATE tasks SET due_date = ? WHERE id = ? AND project_id = ?');
const updateNotes = db.prepare('UPDATE tasks SET notes = ? WHERE id = ? AND project_id = ?');
const updateTask = db.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?');
const renameTask = db.prepare('UPDATE tasks SET title = ? WHERE id = ? AND project_id = ?');
const updatePriority = db.prepare("UPDATE tasks SET priority = ? WHERE id = ? AND project_id = ? AND ? IN ('Low', 'Normal', 'High')");
const setDefaultPriority = db.prepare("UPDATE projects SET default_priority = ? WHERE id = ? AND archived = 0 AND ? IN ('Low', 'Normal', 'High')");
const listProjects = db.prepare(`SELECT p.id, p.name, p.archived, p.default_priority AS defaultPriority,
  (SELECT COUNT(*) FROM tasks t WHERE t.project_id = p.id AND t.completed = 1) AS completedCount,
  (SELECT COUNT(*) FROM tasks t WHERE t.project_id = p.id) AS totalCount
  FROM projects p ORDER BY p.id`);

const send = (res, status, body, type = 'application/json; charset=utf-8') => {
  res.writeHead(status, { 'Content-Type': type, 'X-Content-Type-Options': 'nosniff' });
  res.end(body);
};
const json = (res, status, value) => send(res, status, JSON.stringify(value));

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, 'http://localhost');
  if (req.method === 'GET' && url.pathname === '/health') {
    return json(res, 200, { status: 'ok' });
  }
  if (url.pathname === '/api/projects' && req.method === 'GET') {
    return json(res, 200, listProjects.all());
  }
  if (url.pathname === '/api/projects' && req.method === 'POST') {
    let raw = '';
    try {
      for await (const chunk of req) raw += chunk;
      const data = JSON.parse(raw || '{}');
      const name = typeof data.name === 'string' ? data.name.trim() : '';
      if (!name) return json(res, 400, { error: 'Project name is required' });
      const result = createProject.run(name);
      return json(res, 201, getProject.get(Number(result.lastInsertRowid)));
    } catch {
      return json(res, 400, { error: 'Invalid request' });
    }
  }
  const tasksMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks\/?$/);
  if (tasksMatch) {
    const projectId = Number(tasksMatch[1]);
    if (!getProject.get(projectId)) return json(res, 404, { error: 'Project not found' });
    if (req.method === 'GET') return json(res, 200, listTasks.all(projectId));
    if (req.method === 'POST') {
      if (getProject.get(projectId).archived) return json(res, 403, { error: 'Archived project' });
      try {
        let raw = '';
        for await (const chunk of req) raw += chunk;
        const data = JSON.parse(raw || '{}');
        const title = typeof data.title === 'string' ? data.title.trim() : '';
        if (!title) return json(res, 400, { error: 'Task title is required' });
        const project = getProject.get(projectId);
        const result = createTask.run(projectId, title, project.defaultPriority || 'Normal', projectId);
        const taskId = Number(result.lastInsertRowid);
        addTaskPosition.run(taskId, projectId, nextTaskPosition.get(projectId).position);
        return json(res, 201, getTask.get(taskId));
      } catch {
        return json(res, 400, { error: 'Invalid request' });
      }
    }
  }
  const archiveMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/?$/);
  if (archiveMatch && req.method === 'PATCH') {
    try {
      let raw = '';
      for await (const chunk of req) raw += chunk;
      const data = JSON.parse(raw || '{}');
      const id = Number(archiveMatch[1]);
      const project = getProject.get(id);
      if (!project) return json(res, 404, { error: 'Project not found' });
      if (typeof data.defaultPriority === 'string') {
        if (!['Low', 'Normal', 'High'].includes(data.defaultPriority)) return json(res, 400, { error: 'Invalid priority' });
        if (project.archived) return json(res, 403, { error: 'Archived project' });
        setDefaultPriority.run(data.defaultPriority, id, data.defaultPriority);
      } else if (typeof data.name === 'string') {
        const name = data.name.trim();
        if (!name) return json(res, 400, { error: 'Project name is required' });
        if (project.archived) return json(res, 403, { error: 'Archived project' });
        renameProject.run(name, id);
      } else if (typeof data.archived === 'boolean') {
        setArchived.run(data.archived ? 1 : 0, id);
      } else return json(res, 400, { error: 'Invalid project update' });
      return json(res, 200, getProject.get(id));
    } catch { return json(res, 400, { error: 'Invalid request' }); }
  }
  const taskMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks\/(\d+)\/?$/);
  if (taskMatch && req.method === 'PATCH') {
    try {
      let raw = '';
      for await (const chunk of req) raw += chunk;
      const data = JSON.parse(raw || '{}');
      const projectId = Number(taskMatch[1]);
      const project = getProject.get(projectId);
      if (!project) return json(res, 404, { error: 'Project not found' });
      if (project.archived) return json(res, 403, { error: 'Archived project' });
      const taskId = Number(taskMatch[2]);
      if (Number.isInteger(data.destinationProjectId)) {
        const destination = getProject.get(data.destinationProjectId);
        if (!destination || destination.archived || destination.id === projectId) return json(res, 400, { error: 'Invalid destination project' });
        const position = getTaskPosition.get(taskId, destination.id)?.position ?? nextTaskPosition.get(destination.id).position;
        db.exec('BEGIN');
        try {
          const result = moveTask.run(destination.id, position, taskId, projectId);
          if (!result.changes) { db.exec('ROLLBACK'); return json(res, 404, { error: 'Task not found' }); }
          if (!getTaskPosition.get(taskId, destination.id)) addTaskPosition.run(taskId, destination.id, position);
          db.exec('COMMIT');
        } catch (error) { db.exec('ROLLBACK'); throw error; }
      } else if (typeof data.dueDate === 'string') {
        const trimmed = data.dueDate.trim();
        let canonical = null;
        if (trimmed) {
          const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(trimmed);
          if (!match) return json(res, 400, { error: 'Due date must be a valid YYYY-MM-DD date' });
          const year = Number(match[1]), month = Number(match[2]), day = Number(match[3]);
          const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
          const days = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
          if (year < 1 || month < 1 || month > 12 || day < 1 || day > days[month - 1]) return json(res, 400, { error: 'Due date must be a valid YYYY-MM-DD date' });
          canonical = trimmed;
        }
        const result = updateDueDate.run(canonical, taskId, projectId);
        if (!result.changes) return json(res, 404, { error: 'Task not found' });
      } else if (typeof data.notes === 'string') {
        const result = updateNotes.run(data.notes, taskId, projectId);
        if (!result.changes) return json(res, 404, { error: 'Task not found' });
      } else if (typeof data.priority === 'string') {
        if (!['Low', 'Normal', 'High'].includes(data.priority)) return json(res, 400, { error: 'Invalid priority' });
        const result = updatePriority.run(data.priority, taskId, projectId, data.priority);
        if (!result.changes) return json(res, 404, { error: 'Task not found' });
      } else if (typeof data.title === 'string') {
        const title = data.title.trim();
        if (!title) return json(res, 400, { error: 'Task title is required' });
        const result = renameTask.run(title, taskId, projectId);
        if (!result.changes) return json(res, 404, { error: 'Task not found' });
      } else if (typeof data.completed === 'boolean') {
        const result = updateTask.run(data.completed ? 1 : 0, taskId, projectId);
        if (!result.changes) return json(res, 404, { error: 'Task not found' });
      } else return json(res, 400, { error: 'Invalid task update' });
      return json(res, 200, getTask.get(taskId));
    } catch {
      return json(res, 400, { error: 'Invalid request' });
    }
  }

  const projectMatch = url.pathname.match(/^\/projects\/(\d+)\/?$/);
  if (req.method === 'GET' && projectMatch) {
    const project = getProject.get(Number(projectMatch[1]));
    if (!project) return send(res, 404, 'Not found', 'text/plain; charset=utf-8');
  }
  if (req.method === 'GET' && (url.pathname === '/' || projectMatch)) {
    try {
      const html = await readFile(path.join(root, 'public', 'index.html'));
      return send(res, 200, html, 'text/html; charset=utf-8');
    } catch {
      return send(res, 500, 'Application unavailable', 'text/plain; charset=utf-8');
    }
  }
  if (req.method === 'GET' && url.pathname === '/app.js') {
    try {
      return send(res, 200, await readFile(path.join(root, 'public', 'app.js')), 'text/javascript; charset=utf-8');
    } catch {
      return send(res, 404, 'Not found', 'text/plain; charset=utf-8');
    }
  }
  if (req.method === 'GET' && url.pathname === '/styles.css') {
    try {
      return send(res, 200, await readFile(path.join(root, 'public', 'styles.css')), 'text/css; charset=utf-8');
    } catch {
      return send(res, 404, 'Not found', 'text/plain; charset=utf-8');
    }
  }
  return send(res, 404, 'Not found', 'text/plain; charset=utf-8');
});

const port = Number(process.env.PORT) || 8080;
server.listen(port, '0.0.0.0');

const listSection = document.querySelector('#project-list');
const detailSection = document.querySelector('#project-detail');
const projectContainer = document.querySelector('#projects');
const errorMessage = document.querySelector('#error-message');
const taskContainer = document.querySelector('#tasks');
let activeProjectId = null;
let projectTasks = [];
let allProjects = [];
let appliedDueRange = { from: '', through: '' };
let appliedProjectQuery = '';
let appliedTaskQuery = '';

function normalizeSearch(value) {
  return value.replace(/[ \t]+/g, ' ').toLowerCase();
}

async function loadProjects() {
  const response = await fetch('/api/projects');
  if (!response.ok) throw new Error('Could not load projects');
  const projects = await response.json();
  projectContainer.replaceChildren();
  const filter = document.querySelector('#project-filter').value;
  for (const project of projects.filter(p => Boolean(p.archived) === (filter === 'Archived') && normalizeSearch(p.name).includes(appliedProjectQuery))) {
    const row = document.createElement('div');
    row.className = 'project-row';
    row.dataset.testid = 'project-row';
    const name = document.createElement('span');
    name.textContent = project.name;
    const open = document.createElement('button');
    open.type = 'button';
    open.textContent = 'Open project';
    open.addEventListener('click', () => navigate(`/projects/${project.id}`));
    const summary = document.createElement('span');
    summary.dataset.testid = 'project-summary';
    summary.textContent = `${project.completedCount}/${project.totalCount} completed`;
    const toggle = document.createElement('button');
    toggle.type = 'button';
    toggle.textContent = project.archived ? 'Restore project' : 'Archive project';
    toggle.addEventListener('click', async () => {
      await fetch(`/api/projects/${project.id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ archived: !project.archived }) });
      await loadProjects();
    });
    row.append(name, summary, open, toggle);
    projectContainer.append(row);
  }
}

async function showRoute() {
  const match = location.pathname.match(/^\/projects\/(\d+)\/?$/);
  if (!match) {
    activeProjectId = null;
    appliedProjectQuery = '';
    document.querySelector('#project-search').value = '';
    listSection.hidden = false;
    detailSection.hidden = true;
    await loadProjects();
    return;
  }
  const response = await fetch('/api/projects');
  const projects = await response.json();
  const project = projects.find(item => String(item.id) === match[1]);
  if (!project) {
    navigate('/', true);
    return;
  }
  if (String(activeProjectId) !== match[1]) {
    appliedTaskQuery = '';
    document.querySelector('#task-search').value = '';
    document.querySelector('#task-filter').value = 'All';
    document.querySelector('#priority-filter').value = 'All';
    appliedDueRange = { from: '', through: '' };
    document.querySelector('#due-from').value = '';
    document.querySelector('#due-through').value = '';
  }
  document.querySelector('#detail-name').textContent = project.name;
  document.querySelector('#archived-notice').hidden = !project.archived;
  document.querySelector('#task-title').disabled = Boolean(project.archived);
  document.querySelector('#task-form button').disabled = Boolean(project.archived);
  document.querySelector('#new-project-name').disabled = Boolean(project.archived);
  document.querySelector('#rename-form button').disabled = Boolean(project.archived);
  document.querySelector('#new-project-name').value = project.name;
  const defaultPriority = document.querySelector('#default-task-priority');
  defaultPriority.value = project.defaultPriority || 'Normal';
  defaultPriority.disabled = Boolean(project.archived);
  activeProjectId = project.id;
  listSection.hidden = true;
  detailSection.hidden = false;
  await loadTasks();
}

function navigate(path, replace = false) {
  if (replace) history.replaceState({}, '', path);
  else history.pushState({}, '', path);
  showRoute();
}

document.querySelector('#create-form').addEventListener('submit', async event => {
  event.preventDefault();
  errorMessage.hidden = true;
  const input = document.querySelector('#project-name');
  const response = await fetch('/api/projects', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ name: input.value })
  });
  if (!response.ok) {
    const result = await response.json();
    errorMessage.textContent = result.error || 'Unable to create project';
    errorMessage.hidden = false;
    return;
  }
  input.value = '';
  await loadProjects();
});

async function loadTasks() {
  const [response, projectsResponse] = await Promise.all([
    fetch(`/api/projects/${activeProjectId}/tasks`), fetch('/api/projects')
  ]);
  if (!response.ok || !projectsResponse.ok) return;
  projectTasks = await response.json();
  allProjects = await projectsResponse.json();
  renderTasks();
}

function renderTasks() {
  const filter = document.querySelector('#task-filter').value;
  const priorityFilter = document.querySelector('#priority-filter').value;
  taskContainer.replaceChildren();
  for (const task of projectTasks) {
    if (!normalizeSearch(task.title).includes(appliedTaskQuery)) continue;
    if ((filter === 'Open' && task.completed) || (filter === 'Completed' && !task.completed)) continue;
    if (priorityFilter !== 'All' && task.priority !== priorityFilter) continue;
    if ((appliedDueRange.from || appliedDueRange.through) && !task.dueDate) continue;
    if (task.dueDate && ((appliedDueRange.from && task.dueDate < appliedDueRange.from) || (appliedDueRange.through && task.dueDate > appliedDueRange.through))) continue;
    const row = document.createElement('div');
    row.className = 'task-row';
    row.dataset.testid = 'task-row';
    const title = document.createElement('span');
    title.textContent = task.title;
    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.checked = Boolean(task.completed);
    checkbox.disabled = document.querySelector('#archived-notice').hidden === false;
    checkbox.setAttribute('aria-label', `Complete ${task.title}`);
    checkbox.addEventListener('change', async () => {
      const response = await fetch(`/api/projects/${activeProjectId}/tasks/${task.id}`, {
        method: 'PATCH', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ completed: checkbox.checked })
      });
      if (response.ok) {
        const updated = await response.json();
        task.completed = updated.completed;
        renderTasks();
      }
    });
    const renameInput = document.createElement('input');
    renameInput.type = 'text';
    renameInput.value = task.title;
    renameInput.setAttribute('aria-label', 'New task title');
    const renameButton = document.createElement('button');
    renameButton.type = 'button';
    renameButton.textContent = 'Rename task';
    const archived = document.querySelector('#archived-notice').hidden === false;
    renameInput.disabled = archived;
    renameButton.disabled = archived;
    renameButton.addEventListener('click', async () => {
      const error = document.querySelector('#task-rename-error');
      error.hidden = true;
      const response = await fetch(`/api/projects/${activeProjectId}/tasks/${task.id}`, {
        method: 'PATCH', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title: renameInput.value })
      });
      if (!response.ok) {
        const result = await response.json();
        error.textContent = result.error || 'Unable to rename task';
        error.hidden = false;
        return;
      }
      const updated = await response.json();
      task.title = updated.title;
      renderTasks();
    });
    const priority = document.createElement('select');
    priority.setAttribute('aria-label', 'Task priority');
    for (const value of ['Low', 'Normal', 'High']) {
      const option = document.createElement('option');
      option.value = value;
      option.textContent = value;
      priority.append(option);
    }
    priority.value = task.priority || 'Normal';
    priority.disabled = archived;
    priority.addEventListener('change', async () => {
      const response = await fetch(`/api/projects/${activeProjectId}/tasks/${task.id}`, {
        method: 'PATCH', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ priority: priority.value })
      });
      if (response.ok) {
        task.priority = (await response.json()).priority;
        renderTasks();
      }
    });
    const dueDate = document.createElement('input');
    dueDate.type = 'text';
    dueDate.value = task.dueDate || '';
    dueDate.setAttribute('aria-label', 'Task due date');
    dueDate.disabled = archived;
    const saveDueDate = document.createElement('button');
    saveDueDate.type = 'button';
    saveDueDate.textContent = 'Save due date';
    saveDueDate.disabled = archived;
    saveDueDate.addEventListener('click', async () => {
      const error = document.querySelector('#task-rename-error');
      error.hidden = true;
      const response = await fetch(`/api/projects/${activeProjectId}/tasks/${task.id}`, {
        method: 'PATCH', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ dueDate: dueDate.value })
      });
      if (!response.ok) {
        const result = await response.json();
        error.textContent = result.error || 'Unable to save due date';
        error.hidden = false;
        return;
      }
      task.dueDate = (await response.json()).dueDate;
      dueDate.value = task.dueDate || '';
      renderTasks();
    });
    const notes = document.createElement('textarea');
    notes.setAttribute('aria-label', 'Task notes');
    notes.value = task.notes || '';
    notes.disabled = archived;
    const saveNotes = document.createElement('button');
    saveNotes.type = 'button';
    saveNotes.textContent = 'Save notes';
    saveNotes.disabled = archived;
    saveNotes.addEventListener('click', async () => {
      const response = await fetch(`/api/projects/${activeProjectId}/tasks/${task.id}`, {
        method: 'PATCH', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ notes: notes.value })
      });
      if (response.ok) task.notes = (await response.json()).notes;
    });
    const destinations = document.createElement('select');
    destinations.setAttribute('aria-label', 'Destination project');
    const eligible = allProjects.filter(item => !item.archived && item.id !== Number(activeProjectId));
    for (const destination of eligible) {
      const option = document.createElement('option');
      option.value = destination.id;
      option.textContent = destination.name;
      destinations.append(option);
    }
    const moveButton = document.createElement('button');
    moveButton.type = 'button';
    moveButton.textContent = 'Move task';
    destinations.disabled = archived || eligible.length === 0;
    moveButton.disabled = archived || eligible.length === 0;
    moveButton.addEventListener('click', async () => {
      const response = await fetch(`/api/projects/${activeProjectId}/tasks/${task.id}`, {
        method: 'PATCH', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ destinationProjectId: Number(destinations.value) })
      });
      if (response.ok) await loadTasks();
    });
    row.append(title, checkbox, renameInput, renameButton, priority, dueDate, saveDueDate, notes, saveNotes, destinations, moveButton);
    taskContainer.append(row);
  }
}

document.querySelector('#default-task-priority').addEventListener('change', async event => {
  const response = await fetch(`/api/projects/${activeProjectId}`, {
    method: 'PATCH', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ defaultPriority: event.target.value })
  });
  if (!response.ok) await showRoute();
});
document.querySelector('#task-filter').addEventListener('change', renderTasks);
document.querySelector('#priority-filter').addEventListener('change', renderTasks);
document.querySelector('#apply-due-range').addEventListener('click', () => {
  const from = document.querySelector('#due-from').value.trim();
  const through = document.querySelector('#due-through').value.trim();
  const valid = value => {
    if (!value) return true;
    const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
    if (!match) return false;
    const year = Number(match[1]), month = Number(match[2]), day = Number(match[3]);
    const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
    const days = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
    return year >= 1 && month >= 1 && month <= 12 && day >= 1 && day <= days[month - 1];
  };
  const error = document.querySelector('#task-rename-error');
  if (!valid(from) || !valid(through)) { error.textContent = 'Due range must use valid YYYY-MM-DD dates'; error.hidden = false; return; }
  if (from && through && from > through) { error.textContent = 'Due from must not be after Due through'; error.hidden = false; return; }
  error.hidden = true;
  appliedDueRange = { from, through };
  renderTasks();
});
document.querySelector('#project-filter').addEventListener('change', loadProjects);
document.querySelector('#search-projects').addEventListener('click', () => {
  appliedProjectQuery = normalizeSearch(document.querySelector('#project-search').value.trim());
  loadProjects();
});
document.querySelector('#search-tasks').addEventListener('click', () => {
  appliedTaskQuery = normalizeSearch(document.querySelector('#task-search').value.trim());
  renderTasks();
});
document.querySelector('#task-form').addEventListener('submit', async event => {
  event.preventDefault();
  const error = document.querySelector('#task-error-message');
  error.hidden = true;
  const input = document.querySelector('#task-title');
  const response = await fetch(`/api/projects/${activeProjectId}/tasks`, {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ title: input.value })
  });
  if (!response.ok) {
    const result = await response.json();
    error.textContent = result.error || 'Unable to create task';
    error.hidden = false;
    return;
  }
  input.value = '';
  await loadTasks();
});

document.querySelector('#rename-form').addEventListener('submit', async event => {
  event.preventDefault();
  const error = document.querySelector('#rename-error');
  error.hidden = true;
  const input = document.querySelector('#new-project-name');
  const response = await fetch(`/api/projects/${activeProjectId}`, {
    method: 'PATCH', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ name: input.value })
  });
  if (!response.ok) {
    const result = await response.json();
    error.textContent = result.error || 'Unable to rename project';
    error.hidden = false;
    return;
  }
  await showRoute();
});

document.querySelector('#back-button').addEventListener('click', () => navigate('/'));
window.addEventListener('popstate', showRoute);
showRoute();

